import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"巽","description":"周易正义 - 巽","frontmatter":{"title":"巽","description":"周易正义 - 巽"},"headers":[],"relativePath":"zh/classics/zhengyi/057.md","filePath":"zh/classics/zhengyi/057.md"}'),l={name:"zh/classics/zhengyi/057.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>巽为风</p></blockquote><blockquote><p>卦辞：小亨，利有攸往，利见大人。</p></blockquote><blockquote><p>彖曰：重巽以申命。刚巽乎中正而志行。柔皆顺乎刚，是以小亨、利有攸往、利见大人。。</p></blockquote><h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><p>王弼：全以巽为德，是以小亨也。上下皆巽，不违其令，命乃行也。故申命行事之时，上下不可以不巽也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰“巽者卑顺之名。《说卦》云：“巽，入也。”盖以巽是象风之卦，风行无所不入，故以“入”为训。若施之於人事，能自卑巽者，亦无所不容。然巽之为义，以卑顺为体，以容入为用，故受“巽”名矣。上下皆巽，不为违逆，君唱臣和，教令乃行，故於重巽之卦，以明申命之理。虽上下皆巽，命令可行，然全用卑巽，则所通非大，故曰“小亨”。</p><h3 id="利有攸往。-​" tabindex="-1">利有攸往。 ​ <a class="header-anchor" href="#利有攸往。-​" aria-label="Permalink to “利有攸往。 ​”">​</a></h3><p>王弼：巽悌以行，物无距也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：巽悌以行，物无违距，故曰“利有攸往”。</p><h3 id="利见大人。-​" tabindex="-1">利见大人。 ​ <a class="header-anchor" href="#利见大人。-​" aria-label="Permalink to “利见大人。 ​”">​</a></h3><p>王弼：大人用之，道愈隆。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：但能用巽者，皆无往不利，然大人用巽，其道愈隆，故曰“利见大人”，明上下皆须用巽也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="重巽以申命。-​" tabindex="-1">重巽以申命。 ​ <a class="header-anchor" href="#重巽以申命。-​" aria-label="Permalink to “重巽以申命。 ​”">​</a></h3><p>王弼：命乃行也。未有不巽而命行也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此卦以卑巽为名，以申命为义。故就二体上下皆巽，以明可以申命也。上巽能接於下，下巽能奉於上，上下皆巽，命乃得行，故曰“重巽以申命也”。</p><h3 id="刚巽乎中正而志行。-​" tabindex="-1">刚巽乎中正而志行。 ​ <a class="header-anchor" href="#刚巽乎中正而志行。-​" aria-label="Permalink to “刚巽乎中正而志行。 ​”">​</a></h3><p>王弼：以刚而能用巽，处乎中正，物所与也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“刚巽乎中正而志行”者，虽上下皆巽，若命不可从，则物所不与也。故又因二五之爻，刚而能巽，不失其中，所以志意得行，申其命令也。</p><h3 id="柔皆顺乎刚。-​" tabindex="-1">柔皆顺乎刚。 ​ <a class="header-anchor" href="#柔皆顺乎刚。-​" aria-label="Permalink to “柔皆顺乎刚。 ​”">​</a></h3><p>王弼：明无违逆，故得小亨。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“柔皆顺乎刚”。○正义曰：“柔皆顺乎刚”者，刚虽巽为中正，柔若不顺乎刚，何所申其命乎？故又就初、九各处卦下，柔皆顺刚，无有违逆，所以教命得申，成小亨以下之义也。○注“明无违”至“得小亨”。○正义曰：案《彖》并举“小亨，利有攸往，利见大人”以结之，则柔皆顺刚之意，不事释“小亨”二字，而《注》独言“明无违逆，故得小亨”者，褚氏云：“夫献可替否，其道乃弘：柔皆顺刚，非大通之道，所以文王系‘小亨’之辞，孔子致‘皆顺’之释。”案：王注上下卦之体，皆以巽言之，柔不违刚，正是巽义，故知“皆顺”之言，通释诸辞也。</p><h3 id="是以-小亨-利有攸往-利见大人-。-​" tabindex="-1">是以“小亨，利有攸往，利见大人”。 ​ <a class="header-anchor" href="#是以-小亨-利有攸往-利见大人-。-​" aria-label="Permalink to “是以“小亨，利有攸往，利见大人”。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“是以小亨”以下，释《经》结也。</p><h2 id="《象》曰-随风-巽。君子以申命行事。-​" tabindex="-1">《象》曰：随风，巽。君子以申命行事。 ​ <a class="header-anchor" href="#《象》曰-随风-巽。君子以申命行事。-​" aria-label="Permalink to “《象》曰：随风，巽。君子以申命行事。 ​”">​</a></h2><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“随风，巽”者，两风相随，故曰“随风”，风既相随，物无不顺，故曰“随风，巽”。“君子以申命行事”者，风之随至，非是令初，故君子训之以申命行事也。</p><h2 id="初六-进退-利武人之贞。-​" tabindex="-1">初六：进退，利武人之贞。 ​ <a class="header-anchor" href="#初六-进退-利武人之贞。-​" aria-label="Permalink to “初六：进退，利武人之贞。 ​”">​</a></h2><p>王弼：处令之初，未能服令者也。故进退也。成命齐邪，莫善武人，故“利武人之贞”以整之。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：初六，处令之初，法未宣，著体於柔巽，不能自决，心怀进退，未能从令者也。成命齐邪，莫善威武，既未能从令，则宜用武人之正，以整齐之，故曰“进退，利武人之贞”也。</p><h3 id="《象》曰-进退-志疑也。-​" tabindex="-1">《象》曰：“进退”，志疑也。 ​ <a class="header-anchor" href="#《象》曰-进退-志疑也。-​" aria-label="Permalink to “《象》曰：“进退”，志疑也。 ​”">​</a></h3><p>王弼：巽顺之志，进退疑惧。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志疑”者，欲从之，则未明其令；欲不从，则惧罪及巳，志意怀疑，所以进退也。</p><h3 id="利武人之贞-志治也。-​" tabindex="-1">“利武人之贞”，志治也。 ​ <a class="header-anchor" href="#利武人之贞-志治也。-​" aria-label="Permalink to ““利武人之贞”，志治也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志治也”者，武非行令所宜，而言利武人者，志在使人从治，故曰：“利武人”。其犹《蒙卦》初六《象》曰“利用刑人，以正法也”。</p><h2 id="九二-巽在床下-用史巫纷若-吉-无咎。-​" tabindex="-1">九二：巽在床下，用史巫纷若，吉，无咎。 ​ <a class="header-anchor" href="#九二-巽在床下-用史巫纷若-吉-无咎。-​" aria-label="Permalink to “九二：巽在床下，用史巫纷若，吉，无咎。 ​”">​</a></h2><p>王弼：处巽之中，既在下位，而复以阳居阴，卑巽之甚，故曰：“巽在床下”也。卑甚失正，则入于咎过矣。能以居中而施至卑於神祗，而不用之於威势，则乃至于纷若之吉，而亡其过矣。故曰“用史巫纷若，吉，无咎”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“巽在床下”者，九二处巽下体，而复以阳居阴，卑巽之甚，故曰“巽在床下”。“用史巫纷若，吉，无咎”者，史谓祝史，巫谓巫觋，并是接事鬼神之人也。纷若者，盛多之貌。卑甚失正，则入於过咎。人有威势，易为行恭；神道无形，多生怠慢。若能用居中之德，行至卑之道，用之於神祗，不行之於威势，则能致之於盛多之吉，而无咎过，故曰“用史巫纷若，吉，无咎”也。</p><h3 id="《象》曰-纷若-之-吉-得中也。-​" tabindex="-1">《象》曰：“纷若”之“吉”，得中也。 ​ <a class="header-anchor" href="#《象》曰-纷若-之-吉-得中也。-​" aria-label="Permalink to “《象》曰：“纷若”之“吉”，得中也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“得中”者，用卑巽於神祗，是行得其中，故能致纷若之吉也。</p><h2 id="九三-频巽-吝。-​" tabindex="-1">九三：频巽，吝。 ​ <a class="header-anchor" href="#九三-频巽-吝。-​" aria-label="Permalink to “九三：频巽，吝。 ​”">​</a></h2><p>王弼：频，频蹙，不乐而穷，不得巳之谓也。以其刚正而为四所乘，志穷而巽，是以吝也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“频巽，吝”者，频者，频蹙忧戚之容也，九三体刚居正，为四所乘，是志意穷屈，不得申遂也。既处巽时，只得受其屈辱也，频蹙而巽，鄙吝之道，故曰“频巽，吝”也。</p><h3 id="《象》曰-频巽-之-吝-志穷也。-​" tabindex="-1">《象》曰：“频巽”之“吝”，志穷也。 ​ <a class="header-anchor" href="#《象》曰-频巽-之-吝-志穷也。-​" aria-label="Permalink to “《象》曰：“频巽”之“吝”，志穷也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志穷”者，志意穷屈，所以为吝也。</p><h2 id="六四-悔亡-田获三品。-​" tabindex="-1">六四：悔亡，田获三品。 ​ <a class="header-anchor" href="#六四-悔亡-田获三品。-​" aria-label="Permalink to “六四：悔亡，田获三品。 ​”">​</a></h2><p>王弼：乘刚，悔也，然得位承五，卑得所奉。虽以柔乘刚，而依尊履正，以斯行命，必能获强暴，远不仁者也。获而有益，莫善三品，故曰“悔亡，田获三品”。一曰乾豆，二曰宾客，三曰充君之庖。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“悔亡，田获三品”者，六四有乘刚之悔，然得位承尊，得其所奉，虽以柔乘刚，而依尊履正，以斯行命，必能有功，取譬田猎，能获而有益，莫善三品，所以得悔亡。故曰“悔亡，田获三品”也。三品者，一曰乾豆，二曰宾客，三曰充君之庖厨也。</p><h3 id="《象》曰-田获三品-有功也。-​" tabindex="-1">《象》曰：田获三品，有功也。 ​ <a class="header-anchor" href="#《象》曰-田获三品-有功也。-​" aria-label="Permalink to “《象》曰：田获三品，有功也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“有功”者，田猎有获，以喻行命有功也。</p><h2 id="九五-贞吉-悔亡-无不利。无初有终。先庚三日-后庚三日-吉。-​" tabindex="-1">九五：贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。 ​ <a class="header-anchor" href="#九五-贞吉-悔亡-无不利。无初有终。先庚三日-后庚三日-吉。-​" aria-label="Permalink to “九五：贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。 ​”">​</a></h2><p>王弼：以阳居阳，损於谦巽。然秉乎中正以宣其令，物莫之违，故曰“贞吉，悔亡，无不利”也。化不以渐，卒以刚直用加於物，故初皆不说也。终於中正，邪道以消，故有终也。申命令谓之庚。夫以正齐物，不可卒也；民迷固久，直不可肆也，故先申三日，令著之后，复申三日，然后诛而无咎怨矣。甲、庚，皆申命之谓也。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九五以阳居阳，违於谦巽，是悔也。然执乎中正，以宣其令，物莫之违，是由贞正获吉，故得悔亡而无不利，故曰“贞吉，悔亡，无不利”也。“无初有终”者，若卒用刚直，化不以渐，物皆不说，故曰“无初”也。终於中正，物服其化，故曰“有终”也。“先庚三日，后庚三日，吉”者，申命令谓之庚，民迷固久，申不可卒，故先申之三日，令著之后，复申之三日，然后诛之，民服其罪，无怨而获吉矣，故曰“先庚三日，后庚三日，吉”也。</p><h3 id="《象》曰-九五-之-吉-位正中也。-​" tabindex="-1">《象》曰：“九五”之“吉”，位正中也。 ​ <a class="header-anchor" href="#《象》曰-九五-之-吉-位正中也。-​" aria-label="Permalink to “《象》曰：“九五”之“吉”，位正中也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位正中”者，若不以九居五位，则不能以中正齐物，物之不齐，无由致吉，致吉是由九居五位，故举爻位言之。</p><h2 id="上九-巽在床下-丧其资斧-贞凶。-​" tabindex="-1">上九：巽在床下，丧其资斧，贞凶。 ​ <a class="header-anchor" href="#上九-巽在床下-丧其资斧-贞凶。-​" aria-label="Permalink to “上九：巽在床下，丧其资斧，贞凶。 ​”">​</a></h2><p>王弼：处巽之极，极巽过甚，故曰：“巽在床下”也。斧所以断者也，过巽失正，丧所以断，故曰“丧其资斧，贞凶”也。</p><h3 id="疏-19" tabindex="-1">疏 <a class="header-anchor" href="#疏-19" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“巽在床下”者，上九处巽之极，巽之过甚，故曰“巽在床下”。“丧其资斧”者，斧能斩决，以喻威断也，巽过则不能行威命。命之不行，是丧其所用之斧，故曰“丧其资斧”也。“贞凶”者，失其威断，是正之凶，故曰“贞凶”也。</p><h3 id="《象》曰-巽在床下-上穷也。-丧其资斧-正乎凶也。-​" tabindex="-1">《象》曰“巽在床下”，上穷也。“丧其资斧”，正乎凶也。 ​ <a class="header-anchor" href="#《象》曰-巽在床下-上穷也。-丧其资斧-正乎凶也。-​" aria-label="Permalink to “《象》曰“巽在床下”，上穷也。“丧其资斧”，正乎凶也。 ​”">​</a></h3><h3 id="疏-20" tabindex="-1">疏 <a class="header-anchor" href="#疏-20" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“上穷”者，处上穷巽，故过在床下也。“正乎凶”者，正理须当威断，而丧之，是“正乎凶”也。</p>',80)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
